<?php
declare(strict_types=1);
final class BookingController extends Controller {
 public function index():void{Auth::requireAdmin();$f=['q'=>trim((string)($_GET['q']??'')),'status'=>(string)($_GET['status']??''),'method'=>(string)($_GET['method']??''),'from'=>(string)($_GET['from']??''),'to'=>(string)($_GET['to']??'')];if(!in_array($f['status'],['pending_payment','pending_hotel_payment','confirmed','checked_in','completed','cancelled'],true))$f['status']='';if(!in_array($f['method'],['online','pay_at_hotel'],true))$f['method']='';foreach(['from','to'] as $k)if($f[$k]!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$f[$k]))$f[$k]='';$result=(new Booking())->paginate($f,max(1,(int)($_GET['page']??1)));$this->view('admin/bookings/index',['title'=>'Quản lý đặt phòng','activeMenu'=>'bookings','filters'=>$f,'result'=>$result]);}
